abstract class ReportGenerator {
    protected String title;
    public ReportGenerator(String title) { this.title = title; }

    // Concrete Template Method: Orchestrates report lifecycle
    public final void generateReport() {
        printHeader();
        formatBody();
        printFooter();
    }

    // Shared concrete step
    private void printHeader() {
        System.out.println("========================================");
        System.out.println("REPORT: " + title);
        System.out.println("========================================");
    }

    // Abstract customization step: Subclasses define format
    protected abstract void formatBody();

    // Default concrete step: Subclasses can optionally override
    protected void printFooter() {
        System.out.println("Generated by Enterprise Reporting System");
    }
}

class CsvReportGenerator extends ReportGenerator {
    public CsvReportGenerator(String title) { super(title); }

    @Override
    protected void formatBody() {
        System.out.println("id,name,revenue\n101,Acme,4500.00\n102,Beta,7800.50");
    }
}

public class ReportDemo {
    public static void main(String[] args) {
        ReportGenerator gen = new CsvReportGenerator("Q3 Financials");
        gen.generateReport();
    }
}

