abstract class OrderWorkflow {
    public final void processOrder(double amount) {
        validateFunds(amount);
        executeCharge(amount);
        // Hook method call!
        if (shouldSendGiftWrap()) {
            applyGiftWrap();
        }
        sendConfirmation();
    }

    private void validateFunds(double amount) {
        System.out.println("Checking merchant solvency for $" + amount);
    }

    protected abstract void executeCharge(double amount);

    // HOOK METHOD: Default returns false, subclasses can override to activate
    protected boolean shouldSendGiftWrap() {
        return false;
    }

    protected void applyGiftWrap() {
        System.out.println("Adding satin ribbon and gift card.");
    }

    private void sendConfirmation() {
        System.out.println("Order confirmation email dispatched.");
    }
}

class HolidayOrder extends OrderWorkflow {
    @Override
    protected void executeCharge(double amount) {
        System.out.println("Charging $" + amount + " via Holiday Promotion discount.");
    }
    @Override
    protected boolean shouldSendGiftWrap() {
        return true; // Overrides hook to enable gift wrap!
    }
}

public class WorkflowDemo {
    public static void main(String[] args) {
        OrderWorkflow order = new HolidayOrder();
        order.processOrder(149.99);
    }
}

