abstract class EtlJob {
    protected String datasetName;
    public EtlJob(String datasetName) {
        this.datasetName = datasetName;
    }
    public final void execute() {
        String rawData = extract();
        String cleanData = transform(rawData);
        if (validate(cleanData)) {
            load(cleanData);
        } else {
            System.out.println("Validation failed for " + datasetName);
        }
    }
    protected abstract String extract();
    protected abstract String transform(String rawData);
    protected boolean validate(String cleanData) {
        return cleanData != null && !cleanData.isEmpty();
    }
    protected abstract void load(String cleanData);
}

class CustomerEtlJob extends EtlJob {
    public CustomerEtlJob(String datasetName) {
        super(datasetName);
    }
    @Override
    protected String extract() {
        return "raw_cust_101,john doe";
    }
    @Override
    protected String transform(String rawData) {
        return rawData.toUpperCase().replace("RAW_", "CLEAN_");
    }
    @Override
    protected void load(String cleanData) {
        System.out.println("Loaded into Customer Data Warehouse: " + cleanData);
    }
}

public class EtlApp {
    public static void main(String[] args) {
        EtlJob job = new CustomerEtlJob("Q3_Customers");
        job.execute();
    }
}
